import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

// The only table. Used solely when SESSION_STORE=ephemeral; every row is
// deleted at expiresAt (30 minutes after creation) or on request. See
// convex/README.md "What is stored".
export default defineSchema({
  sessions: defineTable({
    // 128-bit random bearer ID generated by the HTTP action.
    sessionId: v.string(),
    // Validated ConversationState as JSON (may contain health answers), or null.
    conversation: v.union(v.string(), v.null()),
    // Validated quiz progress as JSON (game health only), or null.
    quiz: v.union(v.string(), v.null()),
    expiresAt: v.number(),
  })
    .index("by_session_id", ["sessionId"])
    .index("by_expires_at", ["expiresAt"]),
});
